package set

import "testing"

func TestAddAndContains(t *testing.T) {
	s := New[int]()
	s.Add(1)
	s.Add(2)
	s.Add(2) // duplicate
	if !s.Contains(1) || !s.Contains(2) {
		t.Fatal("should contain 1 and 2")
	}
	if s.Contains(3) {
		t.Fatal("should not contain 3")
	}
	if s.Len() != 2 {
		t.Fatalf("expected len=2 got %d", s.Len())
	}
}

func TestRemove(t *testing.T) {
	s := New[string]()
	s.Add("a")
	s.Add("b")
	s.Remove("a")
	if s.Contains("a") {
		t.Fatal("should not contain 'a' after remove")
	}
	if !s.Contains("b") {
		t.Fatal("should still contain 'b'")
	}
	s.Remove("nonexistent") // no-op
}

func TestUnion(t *testing.T) {
	a := New[int]()
	a.Add(1); a.Add(2)
	b := New[int]()
	b.Add(2); b.Add(3)
	u := a.Union(b)
	if u.Len() != 3 {
		t.Fatalf("expected union len=3, got %d", u.Len())
	}
	for _, v := range []int{1, 2, 3} {
		if !u.Contains(v) {
			t.Fatalf("union should contain %d", v)
		}
	}
}

func TestIntersection(t *testing.T) {
	a := New[int]()
	a.Add(1); a.Add(2); a.Add(3)
	b := New[int]()
	b.Add(2); b.Add(3); b.Add(4)
	i := a.Intersection(b)
	if i.Len() != 2 {
		t.Fatalf("expected intersection len=2, got %d", i.Len())
	}
	if !i.Contains(2) || !i.Contains(3) {
		t.Fatal("intersection should contain 2 and 3")
	}
}

func TestEmptySet(t *testing.T) {
	s := New[float64]()
	if s.Len() != 0 || s.Contains(1.0) {
		t.Fatal("empty set should have len=0 and contain nothing")
	}
}
